SELECT DATE_TRUNC('YEAR', order_date) AS year_start, SUM(amount) FILTER (WHERE channel = 'partner') AS partner_total_amount, AVG(shipping_fee) FILTER (WHERE status = 'CANCELLED') AS cancelled_avg_shipping_fee, APPROX_PERCENTILE(shipping_fee, ARRAY(0.25, 0.5, 0.75)) AS shipping_fee_quartiles, COUNT(*) AS cnt FROM orders GROUP BY DATE_TRUNC('YEAR', order_date) ORDER BY cancelled_avg_shipping_fee NULLS FIRST;
